describe('Session Expiration', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const loginUrl = `${baseUrl}/login`;
  const dashboardUrl = `${baseUrl}/dashboard`;

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.get('input[name="email"]').type('testuser@example.com');
    cy.get('input[name="password"]').type('validPassword123');
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'valid-token-12345');
      win.localStorage.setItem('tokenExpiry', Date.now() + 3600000);
    });
  });

  it('should display session expired message when token times out', () => {
    cy.visit(dashboardUrl);
    cy.get('[data-testid="dashboard-content"]').should('be.visible');

    cy.window().then((win) => {
      win.localStorage.setItem('tokenExpiry', Date.now() - 1000);
    });

    cy.get('button[data-testid="refresh-data"]').click();

    cy.get('[data-testid="session-expired-modal"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]')
      .should('contain', 'Your session has expired')
      .and('contain', 'Please log in again');

    cy.get('[data-testid="session-expired-modal"]').should('have.class', 'visible');
  });

  it('should redirect to login page when user clicks logout on expired session modal', () => {
    cy.visit(dashboardUrl);

    cy.window().then((win) => {
      win.localStorage.setItem('tokenExpiry', Date.now() - 1000);
    });

    cy.get('button[data-testid="refresh-data"]').click();

    cy.get('[data-testid="session-expired-modal"]').should('be.visible');
    cy.get('button[data-testid="session-expired-logout-btn"]').click();

    cy.url().should('include', '/login');
    cy.window().then((win) => {
      expect(win.localStorage.getItem('authToken')).to.be.null;
    });
  });

  it('should handle rapid token expiration checks without multiple modals', () => {
    cy.visit(dashboardUrl);

    cy.window().then((win) => {
      win.localStorage.setItem('tokenExpiry', Date.now() - 1000);
    });

    cy.get('button[data-testid="refresh-data"]').click();
    cy.get('[data-testid="session-expired-modal"]').should('be.visible');

    cy.get('button[data-testid="refresh-data"]').click();

    cy.get('[data-testid="session-expired-modal"]').should('have.length', 1);
  });

  it('should display session expiration warning before complete timeout', () => {
    cy.visit(dashboardUrl);

    const warningThreshold = 300000;
    cy.window().then((win) => {
      win.localStorage.setItem('tokenExpiry', Date.now() + warningThreshold - 10000);
    });

    cy.get('button[data-testid="refresh-data"]').click();

    cy.get('[data-testid="session-warning-banner"]').should('be.visible');
    cy.get('[data-testid="session-warning-banner"]')
      .should('contain', 'Your session will expire soon');

    cy.get('[data-testid="session-expired-modal"]').should('not.exist');
  });

  it('should handle session expiration during API request', () => {
    cy.intercept('GET', '/api/user/data', {
      statusCode: 401,
      body: { error: 'Unauthorized', message: 'Token expired' }
    }).as('expiredTokenRequest');

    cy.visit(dashboardUrl);
    cy.get('button[data-testid="load-more-data"]').click();

    cy.wait('@expiredTokenRequest');

    cy.get('[data-testid="session-expired-modal"]').should('be.visible');
    cy.get('[data-testid="session-expired-message"]')
      .should('contain', 'Your session has expired');
  });

  it('should clear sensitive data from storage on session expiration', () => {
    cy.visit(dashboardUrl);

    cy.window().then((win) => {
      win.localStorage.setItem('authToken', 'valid-token-12345');
      win.localStorage.setItem('userPreferences', JSON.stringify({ theme: 'dark' }));
      win.localStorage.setItem('tokenExpiry', Date.now() - 1000);
    });

    cy.get('button[data-testid="refresh-data"]').click();
    cy.get('[data-testid="session-expired-modal"]').should('be.visible');
    cy.get('button[data-testid="session-expired-logout-btn"]').click();

    cy.window().then((win) => {
      expect(win.localStorage.getItem('authToken')).to.be.null;
      expect(win.localStorage.getItem('tokenExpiry')).to.be.null;
    });
  });
});
